#!/usr/bin/env bash
# guards/tests/credclass-lib.test.sh -- tests for hooks/credclass-lib.sh.
#
# The expected classes below were generated by running the ORIGINAL functions
# (credfile-guard.sh at v0.2.9, before they moved into the lib) over the same
# paths, and are committed as data: the move must not change any answer. The
# table covers every deny-class and ask-class name, the .env.example family
# exceptions, a private-key content sniff on an innocuously named file, *.pub,
# known_hosts and config. Fixtures are generated at run time under a temp HOME;
# keys come from ssh-keygen / openssl and have never been used for anything.
#
# Needs: bash, ssh-keygen, openssl, realpath.

set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LIB="${CREDCLASS_LIB:-$HERE/../hooks/credclass-lib.sh}"

T="$(mktemp -d)"
trap 'rm -rf "$T"' EXIT
export HOME="$T/home"
mkdir -p "$HOME/.ssh" "$HOME/.aws" "$HOME/.kube" "$HOME/proj" "$HOME/.config/gcloud" "$HOME/.docker" "$HOME/.gnupg/private-keys-v1.d"
ssh-keygen -q -t ed25519 -N "" -f "$HOME/.ssh/id_ed25519" -C throwaway
openssl ecparam -genkey -name prime256v1 -noout -out "$HOME/proj/innocuous-name.txt" 2>/dev/null
printf 'hello\n' > "$HOME/proj/README.md"

# The inputs the lib documents as the caller's job (read by the sourced functions).
# shellcheck disable=SC2034
CWD="$HOME/proj"
SNIFF_MAX_BYTES=10485760
PRIVATE_KEY_RE='-----BEGIN ([A-Z0-9]+ )*PRIVATE KEY( BLOCK)?-----'
# shellcheck source=guards/hooks/credclass-lib.sh
. "$LIB" || { echo "FAIL: cannot source $LIB"; exit 1; }

pass=0 fail=0
check() { # check DESCRIPTION WANT GOT
  if [ "$2" = "$3" ]; then pass=$((pass + 1)); else fail=$((fail + 1)); echo "FAIL: $1 (wanted '$2', got '$3')"; fi
}

# path | class (deny, ask, none) | reason
CLASSES='
@H@/.ssh/id_ed25519|deny|SSH key material under ~/.ssh
@H@/.ssh/id_rsa|deny|SSH key material under ~/.ssh
@H@/.ssh/id_ed25519.pub|none|-
@H@/.ssh/known_hosts|none|-
@H@/.ssh/known_hosts.old|none|-
@H@/.ssh/config|none|-
@H@/.ssh/authorized_keys|none|-
@H@/.ssh/authorized_keys2|none|-
@H@/.ssh/deploy_key|deny|SSH key material under ~/.ssh
@H@/.ssh/Config|none|-
@H@/.aws/credentials|deny|AWS credentials file
@H@/.aws/config|none|-
@H@/.kube/config|ask|kubeconfig
@H@/.kube/prod.kubeconfig|ask|kubeconfig
@H@/.config/gcloud/application_default_credentials.json|deny|gcloud credentials
@H@/.config/gcloud/access_tokens.db|none|-
@H@/.config/gcloud/legacy_credentials.json|deny|gcloud credentials
@H@/.docker/config.json|deny|docker registry auth
@H@/.gnupg/private-keys-v1.d/abc.key|deny|GPG private keyring
@H@/.gnupg/secring.gpg|deny|GPG private keyring
@H@/proj/.netrc|deny|.netrc credentials
@H@/proj/_netrc|deny|.netrc credentials
@H@/proj/.pgpass|deny|.pgpass credentials
@H@/proj/.git-credentials|deny|git credential store
@H@/proj/.npmrc|ask|package-registry token file
@H@/proj/.pypirc|ask|package-registry token file
@H@/proj/kubeconfig|ask|kubeconfig
@H@/proj/staging.kubeconfig|ask|kubeconfig
@H@/proj/.env|ask|environment file (.env)
@H@/proj/.env.local|ask|environment file (.env)
@H@/proj/.env.production|ask|environment file (.env)
@H@/proj/prod.env|ask|environment file (.env)
@H@/proj/.ENV|ask|environment file (.env)
@H@/proj/.env.example|none|-
@H@/proj/.env.sample|none|-
@H@/proj/.env.template|none|-
@H@/proj/.env.dist|none|-
@H@/proj/app.env.example|none|-
@H@/proj/app.env.sample|none|-
@H@/proj/app.env.template|none|-
@H@/proj/id_rsa|deny|SSH private key
@H@/proj/id_dsa|deny|SSH private key
@H@/proj/id_ecdsa|deny|SSH private key
@H@/proj/id_ed25519|deny|SSH private key
@H@/proj/keystore.p12|deny|keystore / password database
@H@/proj/cert.pfx|deny|keystore / password database
@H@/proj/store.jks|deny|keystore / password database
@H@/proj/app.keystore|deny|keystore / password database
@H@/proj/vault.kdbx|deny|keystore / password database
@H@/proj/terraform.tfstate|ask|terraform state (contains secrets)
@H@/proj/terraform.tfstate.backup|ask|terraform state (contains secrets)
@H@/proj/my-service-account.json|deny|service-account / client-secret JSON
@H@/proj/serviceaccount-prod.json|deny|service-account / client-secret JSON
@H@/proj/aws-credentials.json|deny|service-account / client-secret JSON
@H@/proj/client_secret_123.json|deny|service-account / client-secret JSON
@H@/proj/innocuous-name.txt|deny|file contains a private key
@H@/proj/README.md|none|-
@H@/proj/missing-file.txt|none|-
@H@/proj/config|none|-
@H@/proj/package.json|none|-
@H@/proj|none|-
@H@/.ssh|none|-
'
while IFS='|' read -r raw want_class want_reason; do
  [ -n "$raw" ] || continue
  p="$(resolve_path "${raw//@H@/$HOME}")"
  if why="$(sensitive_reason "$p")"; then
    if is_ask_class "$why"; then cls=ask; else cls=deny; fi
  else
    why="-"; cls=none
  fi
  check "class of ${raw//@H@/}" "$want_class" "$cls"
  check "reason of ${raw//@H@/}" "$want_reason" "$why"
done <<< "$CLASSES"

DIRS='
@H@/.ssh|credential directory
@H@/.aws|credential directory
@H@/.kube|credential directory
@H@/.gnupg|credential directory
@H@/.config/gcloud|credential directory
@H@/.docker|credential directory
@H@/proj|-
@H@/.config|-
@H@/.sshx|-
@H@/.config/gcloud/sub|-
'
while IFS='|' read -r raw want; do
  [ -n "$raw" ] || continue
  if got="$(sensitive_dir_reason "${raw//@H@/$HOME}")"; then :; else got="-"; fi
  check "dir class of ${raw//@H@/}" "$want" "$got"
done <<< "$DIRS"

# shellcheck disable=SC2088
# resolve_path: ~, $HOME, ${HOME}, relative-to-CWD, and dot-dot all normalise.
check "resolve ~/x" "$HOME/x" "$(resolve_path '~/x')"
check "resolve ~" "$HOME" "$(resolve_path '~')"
check 'resolve $HOME/x' "$HOME/x" "$(resolve_path '$HOME/x')"
check 'resolve ${HOME}/x' "$HOME/x" "$(resolve_path '${HOME}/x')"
check "resolve relative" "$HOME/proj/a/b" "$(resolve_path 'a/b')"
check "resolve dot-dot" "$HOME/.ssh/id_ed25519" "$(resolve_path '../.ssh/x/../id_ed25519')"
check "resolve empty" "" "$(resolve_path '')"

# is_ask_class: exactly the five ask reasons.
for r in "environment file (.env)" "kubeconfig" "package-registry token file" "terraform state (contains secrets)" "glob targets .env files"; do
  is_ask_class "$r" && v=ask || v=deny
  check "is_ask_class '$r'" ask "$v"
done
for r in "AWS credentials file" "SSH private key" "file contains a private key" "glob targets credential files" ""; do
  is_ask_class "$r" && v=ask || v=deny
  check "is_ask_class '$r'" deny "$v"
done

# The sniff honours SNIFF_MAX_BYTES: a key header past the cap is not seen.
{ head -c 4096 /dev/zero | tr '\0' 'a'; cat "$HOME/proj/innocuous-name.txt"; } > "$HOME/proj/late-key.txt"
SNIFF_MAX_BYTES=100
sensitive_reason "$HOME/proj/late-key.txt" >/dev/null && v=hit || v=miss
check "sniff cap respected" miss "$v"
SNIFF_MAX_BYTES=10485760
sensitive_reason "$HOME/proj/late-key.txt" >/dev/null && v=hit || v=miss
check "sniff past offset within cap" hit "$v"

echo "credclass-lib: $pass passed, $fail failed"
[ "$fail" -eq 0 ]
